using System.Data; using System.Data.SqlClient; using System.Web.Script.Services; using System.Web.Services;
namespace WamoApp { public partial class AccountPage : ProtectedPage { [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetLanguages() { return new { success = true, data = LocalizationHelper.GetLanguages() }; } [WebMethod][ScriptMethod(ResponseFormat = ResponseFormat.Json)] public static object GetAccountSummary() { SessionManager.RequireAuthenticated(); var userId = SessionManager.GetCurrentUserId(); var customer = DbHelper.ExecuteDataTable(@"SELECT TOP 1 c.CustomerNumber, c.FullName, c.PhoneNumber, c.WhatsAppNumber, c.Email, c.AddressLine, s.SectionName, b.BlockNumber, h.HouseNumber, c.CustomerType, c.ServiceName, c.PreferredSchedule, c.Status FROM Customers c LEFT JOIN Sections s ON s.SectionID = c.SectionID LEFT JOIN Blocks b ON b.BlockID = c.BlockID LEFT JOIN Houses h ON h.HouseID = c.HouseID WHERE c.LinkedUserID = @UserID OR c.Email = (SELECT Email FROM Users WHERE UserID = @UserID)", CommandType.Text, new SqlParameter("@UserID", userId)); var payments = DbHelper.ExecuteDataTable("SELECT TOP 10 InvoiceNumber, AmountDue, AmountPaid, BalanceAmount, PaymentDate, Status FROM PaymentsView WHERE UserID = @UserID ORDER BY PaymentDate DESC", CommandType.Text, new SqlParameter("@UserID", userId)); var requests = DbHelper.ExecuteDataTable("SELECT TOP 10 RequestNumber, ServiceName, PreferredDate, Status FROM CollectionRequests WHERE CustomerID = @UserID ORDER BY CreatedDate DESC", CommandType.Text, new SqlParameter("@UserID", userId)); var complaints = DbHelper.ExecuteDataTable("SELECT TOP 10 ComplaintNumber, Subject, Description, Status, Response FROM Complaints WHERE CustomerID = @UserID ORDER BY CreatedDate DESC", CommandType.Text, new SqlParameter("@UserID", userId)); var notifications = DbHelper.ExecuteDataTable("SELECT TOP 10 NotificationType, Title, Message, CreatedDate, IsRead FROM Notifications WHERE UserID = @UserID ORDER BY CreatedDate DESC", CommandType.Text, new SqlParameter("@UserID", userId)); return new { success = true, data = new { Profile = DbHelper.ToDictionaryList(customer), Payments = DbHelper.ToDictionaryList(payments), Requests = DbHelper.ToDictionaryList(requests), Complaints = DbHelper.ToDictionaryList(complaints), Notifications = DbHelper.ToDictionaryList(notifications) } }; } } }
